ALTER TABLE exchange_requests ADD COLUMN all_files_delivered_at TIMESTAMP(6) NULL AFTER published_at;
ALTER TABLE request_files ADD COLUMN first_delivered_at TIMESTAMP(6) NULL AFTER antivirus_status, ADD COLUMN source_deleted_at TIMESTAMP(6) NULL AFTER first_delivered_at, ADD COLUMN target_deleted_at TIMESTAMP(6) NULL AFTER source_deleted_at;
ALTER TABLE download_grants ADD COLUMN download_slot_no SMALLINT UNSIGNED NULL AFTER portal_zone, ADD COLUMN target_storage_revision_id BINARY(16) NULL AFTER download_slot_no, ADD COLUMN target_bucket VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NULL AFTER target_storage_revision_id, ADD COLUMN target_object_key VARCHAR(512) CHARACTER SET ascii COLLATE ascii_bin NULL AFTER target_bucket, ADD COLUMN target_version_id VARCHAR(512) CHARACTER SET ascii COLLATE ascii_bin NULL AFTER target_object_key, ADD COLUMN expected_sha256 BINARY(32) NULL AFTER target_version_id, ADD COLUMN expected_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0 AFTER expected_sha256, ADD COLUMN fencing_token BIGINT UNSIGNED NOT NULL DEFAULT 0 AFTER status, ADD COLUMN lease_expires_at TIMESTAMP(6) NULL AFTER fencing_token, ADD COLUMN last_checked_at TIMESTAMP(6) NULL AFTER lease_expires_at, ADD COLUMN error_code VARCHAR(64) NULL AFTER bytes_sent, ADD COLUMN version BIGINT UNSIGNED NOT NULL DEFAULT 1 AFTER error_code;
ALTER TABLE download_grants ADD COLUMN idempotency_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN idempotency_payload_sha256 BINARY(32) NULL, ADD COLUMN grant_token_ciphertext VARBINARY(512) NULL, ADD UNIQUE KEY uk_download_grant_idempotency(user_id,file_id,idempotency_key);
CREATE TABLE download_deliveries(id BINARY(16) PRIMARY KEY,grant_id BINARY(16) NOT NULL UNIQUE,request_id BINARY(16) NOT NULL,file_id BINARY(16) NOT NULL,user_id BINARY(16) NOT NULL,status ENUM('STARTED','COMPLETED','INTERRUPTED') NOT NULL,bytes_sent BIGINT UNSIGNED NOT NULL DEFAULT 0,computed_sha256 BINARY(32),started_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),finished_at TIMESTAMP(6),error_code VARCHAR(64),CONSTRAINT fk_delivery_grant FOREIGN KEY(grant_id) REFERENCES download_grants(id),CONSTRAINT fk_delivery_request FOREIGN KEY(request_id) REFERENCES exchange_requests(id),CONSTRAINT fk_delivery_file FOREIGN KEY(file_id) REFERENCES request_files(id),INDEX ix_delivery_request(request_id,file_id,status),INDEX ix_delivery_user(user_id,started_at)) ENGINE=InnoDB;
UPDATE exchange_requests SET expires_at=DATE_ADD(published_at,INTERVAL IF(direction='OFFICE_TO_PROD',8,24) HOUR) WHERE status IN ('READY','PARTIALLY_DELIVERED','DELIVERED') AND published_at IS NOT NULL AND expires_at IS NULL;
